sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    try {
        gs.info('Business Rule Execution Started.');

        // Fetch the groups the creator belongs to
        var creatorSysID = current.getValue('opened_by'); // Use getValue() to fetch the opened_by field value
        gs.info('Creator sys_id: ' + creatorSysID);

        var creatorGroups = getUserGroups(creatorSysID);
        gs.info('Creator Groups: ' + JSON.stringify(creatorGroups));

        if (!creatorGroups || creatorGroups.length === 0) {
            gs.info('No groups found for the user creating the record.');
            return;
        }

        // Dynamically extract the instance identifier from the group names
        var instanceIdentifier = extractInstanceIdentifier(creatorGroups);
        if (!instanceIdentifier) {
            gs.info('No instance identifier found in the user groups.');
            return;
        }
        gs.info('Using Instance Identifier: ' + instanceIdentifier);

        // Log the raw value of the prm_user_email_lst field
        gs.info('Raw value of prm_user_email_lst field: ' + current.prm_user_email_lst);

        // Ensure the field value is correctly accessed and processed
        var emailList = current.getValue('prm_user_email_lst'); // Use getValue() to fetch the field value
        gs.info('Fetched Email List using getValue(): ' + emailList);

        if (!emailList || emailList.trim() === '') {
            gs.info('prm_user_email_lst field is empty or undefined.');
            return; // Exit the script if the field is empty
        }

        var emailArray = emailList.split(',').map(email => email.trim()); // Split and trim email IDs
        gs.info('Email Array after splitting and trimming: ' + JSON.stringify(emailArray));

        // Determine approver roles based on creator's groups and state
        var approverRoles = determineApproverRoles(creatorGroups, current.getValue('state'), instanceIdentifier); // Pass instanceIdentifier dynamically
        gs.info('Approver Roles determined: ' + approverRoles.join(','));

        // Filter email IDs based on approver roles
        var filteredEmails = filterEmailsByRoles(emailArray, approverRoles);
        gs.info('Filtered Emails: ' + filteredEmails.join(','));

        // Additional logic for state 8
        if (current.getValue('state') === '8') {
            gs.info(`State is 8, adding users from groups Infodir-iQube-${instanceIdentifier}-PRM-ReqrProc and Infodir-iQube-${instanceIdentifier}-PRM-SglApprvr.`);
            var state8Emails = getEmailsFromGroups([`Infodir-iQube-${instanceIdentifier}-PRM-ReqrProc`, `Infodir-iQube-${instanceIdentifier}-PRM-SglApprvr`]);
            gs.info('Emails from state 8 groups: ' + state8Emails.join(','));
            filteredEmails = filteredEmails.concat(state8Emails); // Add state 8 emails
        }

        // Additional logic for state 9
        if (current.getValue('state') === '9') {
            gs.info(`State is 9, adding users from group Infodir-iQube-${instanceIdentifier}-PRM-Apprvr.`);
            var state9Emails = getEmailsFromGroups([`Infodir-iQube-${instanceIdentifier}-PRM-Apprvr`]);
            gs.info('Emails from state 9 group: ' + state9Emails.join(','));
            filteredEmails = filteredEmails.concat(state9Emails); // Add state 9 emails
        }

        // Remove duplicates from the email list
        filteredEmails = [...new Set(filteredEmails)];
        gs.info('Final filtered email list after removing duplicates: ' + filteredEmails.join(','));

        // Update the field with the filtered email list
        current.setValue('prm_user_email_lst', filteredEmails.join(',')); // Use setValue() to update the field
        current.update();
        gs.info('Updated prm_user_email_lst field with filtered emails: ' + filteredEmails.join(','));

        gs.info('Business Rule Execution Completed.');
    } catch (err) {
        gs.error('Error filtering email list: ' + err.message + '\n' + err.stack);
    }

    // Function to fetch groups for a user
    function getUserGroups(userSysID) {
        gs.info('Fetching groups for user sys_id: ' + userSysID);
        var groups = [];
        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('user', userSysID);
        gr.query();
        while (gr.next()) {
            var groupSysID = gr.group.sys_id.toString();
            var groupName = gr.group.name.toString();
            gs.info('Found group: sys_id=' + groupSysID + ', name=' + groupName);
            groups.push({
                sys_id: groupSysID,
                name: groupName
            });
        }
        gs.info('Total groups fetched for user: ' + groups.length);
        return groups;
    }

    // Function to extract the instance identifier from group names
    function extractInstanceIdentifier(groups) {
        gs.info('Extracting instance identifier from group names.');
        for (var i = 0; i < groups.length; i++) {
            var groupName = groups[i].name;
            var match = groupName.match(/^Infodir-iQube-([A-Za-z0-9-]+)-PRM/); // Regular expression to extract instance identifier
            if (match && match[1]) {
                return match[1]; // Return the matched instance identifier
            }
        }
        return null; // Return null if no instance identifier is found
    }

    // Function to determine approver roles based on creator's groups and state
    function determineApproverRoles(creatorGroups, state, instanceIdentifier) {
        gs.info('Determining approver roles based on creator groups and state: ' + state);
        var approverRoles = [];
        var creatorRoleNames = creatorGroups.map(group => group.name);
        gs.info('Creator Role Names: ' + JSON.stringify(creatorRoleNames));

        creatorRoleNames.forEach(role => {
            gs.info('Processing role: ' + role);
            if (role === `Infodir-iQube-${instanceIdentifier}-PRM-ReqrNAUTH-Reqr`) {
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrBsigner-L1Apprvr`);
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L1Apprvr`);
                if (state === '7') {
                    approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L2Apprvr`);
                }
            } else if (role === `Infodir-iQube-${instanceIdentifier}-PRM-ApprvrBsigner-Reqr`) {
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L1Apprvr`);
            } else if (role === `Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-Reqr`) {
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L1Apprvr (another one)`);
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrBsigner-L1Apprvr`);
            }
        });
        gs.info('Approver Roles determined: ' + approverRoles.join(','));
        return approverRoles;
    }

    // Function to filter email IDs based on approver roles
    function filterEmailsByRoles(emailArray, approverRoles) {
        gs.info('Filtering emails based on approver roles.');
        var filteredEmails = [];
        var gr = new GlideRecord('sys_user');
        gr.addQuery('email', 'IN', emailArray.join(',')); // Query users with the provided email IDs
        gr.query();
        while (gr.next()) {
            var userSysID = gr.sys_id.toString();
            var userEmail = gr.email.toString();
            gs.info('Processing user: sys_id=' + userSysID + ', email=' + userEmail);

            var userGroups = getUserGroups(userSysID); // Fetch groups for the user
            var userRoleNames = userGroups.map(group => group.name);
            gs.info('User Role Names: ' + JSON.stringify(userRoleNames));

            var hasApproverRole = approverRoles.some(role => userRoleNames.includes(role)); // Check if user has any approver role
            gs.info('User has approver role: ' + hasApproverRole);

            if (hasApproverRole) {
                filteredEmails.push(userEmail); // Add email to the filtered list
                gs.info('Email added to filtered list: ' + userEmail);
            }
        }
        gs.info('Total filtered emails: ' + filteredEmails.length);
        return filteredEmails;
    }

    // Function to get emails of users belonging to specific groups
    function getEmailsFromGroups(groupNames) {
        gs.info('Fetching emails for groups: ' + groupNames.join(','));
        var emails = [];
        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('group.name', 'IN', groupNames.join(',')); // Query users in the specified groups
        gr.query();
        while (gr.next()) {
            var userEmail = gr.user.email.toString();
            if (userEmail) {
                emails.push(userEmail);
                gs.info('Found email: ' + userEmail);
            }
        }
        gs.info('Total emails fetched for groups: ' + emails.length);
        return emails;
    }
})(current, previous);
